import base64
import json
from copy import deepcopy

from .constants import NetworkConfig


CANONICAL_FIELD_ORDER = [
    "type",
    "name",
    "description",
    "image",
    "services",
    "aliases",
    "x402Support",
    "active",
    "registrations",
    "externalRegistrations",
    "supportedTrust",
    "agentWallet",
]

REGISTRATION_TYPE = "https://eips.ethereum.org/EIPS/eip-8004#registration-v1"


def build_registration(
    network: NetworkConfig,
    *,
    name: str,
    description: str,
    image: str,
    services: list[dict] | None = None,
    x402_support: bool = False,
    active: bool = True,
    registrations: list[dict] | None = None,
    supported_trust: list[str] | None = None,
) -> dict:
    registration = {
        "type": REGISTRATION_TYPE,
        "name": name,
        "description": description,
        "image": image,
        "services": deepcopy(services or []),
        "x402Support": bool(x402_support),
        "active": bool(active),
        "registrations": deepcopy(registrations or []),
        "supportedTrust": list(supported_trust or []),
    }
    return _order_registration(registration)


def normalize_registration(
    registration: dict,
    *,
    network: NetworkConfig,
    default_name: str | None = None,
    default_description: str | None = None,
    default_image: str | None = None,
    default_services: list[dict] | None = None,
    default_x402_support: bool | None = None,
    default_active: bool | None = None,
    default_registrations: list[dict] | None = None,
    default_supported_trust: list[str] | None = None,
) -> dict:
    if not isinstance(registration, dict):
        raise ValueError("registration must be a JSON object")

    normalized = deepcopy(registration)
    if not normalized.get("type"):
        normalized["type"] = REGISTRATION_TYPE
    elif normalized["type"] != REGISTRATION_TYPE:
        raise ValueError(f"registration.type must be {REGISTRATION_TYPE}")

    if not normalized.get("name"):
        if default_name:
            normalized["name"] = default_name
        else:
            raise ValueError("registration.name is required")

    if not normalized.get("description"):
        if default_description:
            normalized["description"] = default_description
        else:
            raise ValueError("registration.description is required")

    if not normalized.get("image"):
        if default_image:
            normalized["image"] = default_image
        else:
            raise ValueError("registration.image is required")

    services = normalized.get("services")
    if services is None:
        normalized["services"] = deepcopy(default_services or [])
    elif not isinstance(services, list):
        raise ValueError("registration.services must be an array")

    if "x402Support" not in normalized:
        normalized["x402Support"] = (
            bool(default_x402_support) if default_x402_support is not None else False
        )
    else:
        normalized["x402Support"] = bool(normalized["x402Support"])

    if "active" not in normalized:
        normalized["active"] = (
            bool(default_active) if default_active is not None else True
        )
    else:
        normalized["active"] = bool(normalized["active"])

    registrations = normalized.get("registrations")
    if registrations is None:
        normalized["registrations"] = deepcopy(default_registrations or [])
    elif not isinstance(registrations, list):
        raise ValueError("registration.registrations must be an array")

    supported_trust = normalized.get("supportedTrust")
    if supported_trust is None:
        normalized["supportedTrust"] = list(default_supported_trust or [])
    elif not isinstance(supported_trust, list):
        raise ValueError("registration.supportedTrust must be an array")

    aliases = normalized.get("aliases")
    if aliases is not None and not isinstance(aliases, list):
        raise ValueError("registration.aliases must be an array")

    external_registrations = normalized.get("externalRegistrations")
    if external_registrations is not None and not isinstance(
        external_registrations, list
    ):
        raise ValueError("registration.externalRegistrations must be an array")

    _validate_registration(normalized)
    return _order_registration(normalized)


def encode_agent_uri(registration: dict) -> str:
    payload = json.dumps(
        _order_registration(registration),
        separators=(",", ":"),
        ensure_ascii=True,
    ).encode("utf-8")
    encoded = base64.b64encode(payload).decode("ascii")
    return f"data:application/json;base64,{encoded}"


def decode_agent_uri(agent_uri: str) -> dict:
    normalized_uri = sanitize_agent_uri(agent_uri)
    if not isinstance(normalized_uri, str) or not normalized_uri.startswith(
        "data:application/json;base64,"
    ):
        raise ValueError(
            "Unsupported agent URI format. Expected data:application/json;base64,... "
            "If the contract returned a quoted tokenURI, strip the wrapping quotes before decoding."
        )
    encoded = normalized_uri.split(",", 1)[1]
    decoded = base64.b64decode(encoded)
    registration = json.loads(decoded.decode("utf-8"))
    if not isinstance(registration, dict):
        raise ValueError("Decoded agent URI is not a JSON object")
    return registration


def sanitize_agent_uri(agent_uri: str) -> str:
    if not isinstance(agent_uri, str):
        raise ValueError("Agent URI must be a string")
    normalized = agent_uri.strip()
    if len(normalized) >= 2 and normalized[0] == normalized[-1] == '"':
        normalized = normalized[1:-1]
    return normalized


def _validate_registration(registration: dict) -> None:
    for field in (
        "type",
        "name",
        "description",
        "image",
        "services",
        "x402Support",
        "active",
        "registrations",
        "supportedTrust",
    ):
        if field not in registration:
            raise ValueError(f"registration.{field} is required")

    if registration["type"] != REGISTRATION_TYPE:
        raise ValueError(f"registration.type must be {REGISTRATION_TYPE}")

    if not isinstance(registration["name"], str) or not registration["name"].strip():
        raise ValueError("registration.name must be a non-empty string")

    for field in ("description", "image"):
        if not isinstance(registration[field], str) or not registration[field].strip():
            raise ValueError(f"registration.{field} must be a non-empty string")

    if not isinstance(registration["services"], list) or not registration["services"]:
        raise ValueError("registration.services must be a non-empty array")
    for index, service in enumerate(registration["services"]):
        if not isinstance(service, dict):
            raise ValueError(f"registration.services[{index}] must be an object")
        for field in ("name", "endpoint"):
            value = service.get(field)
            if not isinstance(value, str) or not value.strip():
                raise ValueError(
                    f"registration.services[{index}].{field} must be a non-empty string"
                )
        version = service.get("version")
        if version is not None and (
            not isinstance(version, str) or not version.strip()
        ):
            raise ValueError(
                f"registration.services[{index}].version must be a non-empty string"
            )
        for list_field in ("skills", "domains"):
            if list_field in service and (
                not isinstance(service[list_field], list)
                or not all(
                    isinstance(item, str) and item.strip()
                    for item in service[list_field]
                )
            ):
                raise ValueError(
                    f"registration.services[{index}].{list_field} must be a string array"
                )
        for string_field in (
            "metadata",
            "registry",
            "registryId",
            "agentHost",
            "status",
        ):
            value = service.get(string_field)
            if value is not None and (
                not isinstance(value, str) or not value.strip()
            ):
                raise ValueError(
                    f"registration.services[{index}].{string_field} must be a non-empty string"
                )
        for list_field in ("supportedAssets", "supportedNetworks"):
            if list_field in service and (
                not isinstance(service[list_field], list)
                or not all(
                    isinstance(item, str) and item.strip()
                    for item in service[list_field]
                )
            ):
                raise ValueError(
                    f"registration.services[{index}].{list_field} must be a string array"
                )
        if "primary" in service and not isinstance(service["primary"], bool):
            raise ValueError(f"registration.services[{index}].primary must be a boolean")

    aliases = registration.get("aliases", [])
    if aliases is not None:
        if not isinstance(aliases, list):
            raise ValueError("registration.aliases must be an array")
        for index, alias in enumerate(aliases):
            if not isinstance(alias, dict):
                raise ValueError(f"registration.aliases[{index}] must be an object")
            for field in ("type", "endpoint"):
                value = alias.get(field)
                if not isinstance(value, str) or not value.strip():
                    raise ValueError(
                        f"registration.aliases[{index}].{field} must be a non-empty string"
                    )
            if "primary" in alias and not isinstance(alias["primary"], bool):
                raise ValueError(
                    f"registration.aliases[{index}].primary must be a boolean"
                )

    if not isinstance(registration["registrations"], list):
        raise ValueError("registration.registrations must be an array")
    for index, item in enumerate(registration["registrations"]):
        if not isinstance(item, dict):
            raise ValueError(f"registration.registrations[{index}] must be an object")
        if not isinstance(item.get("agentId"), int):
            raise ValueError(
                f"registration.registrations[{index}].agentId must be an integer"
            )
        agent_registry = item.get("agentRegistry")
        if not isinstance(agent_registry, str) or not agent_registry.strip():
            raise ValueError(
                f"registration.registrations[{index}].agentRegistry must be a non-empty string"
            )

    supported_trust = registration.get("supportedTrust")
    if not isinstance(supported_trust, list) or not supported_trust or not all(
        isinstance(item, str) and item.strip() for item in supported_trust
    ):
        raise ValueError("registration.supportedTrust must be a non-empty string array")

    external_registrations = registration.get("externalRegistrations", [])
    if external_registrations is not None:
        if not isinstance(external_registrations, list):
            raise ValueError("registration.externalRegistrations must be an array")
        for index, item in enumerate(external_registrations):
            if not isinstance(item, dict):
                raise ValueError(
                    f"registration.externalRegistrations[{index}] must be an object"
                )
            for field in (
                "registry",
                "registryId",
                "name",
                "agentHost",
                "version",
                "status",
            ):
                value = item.get(field)
                if value is not None and (
                    not isinstance(value, str) or not value.strip()
                ):
                    raise ValueError(
                        f"registration.externalRegistrations[{index}].{field} must be a non-empty string"
                    )
            for field in ("registry", "registryId"):
                value = item.get(field)
                if not isinstance(value, str) or not value.strip():
                    raise ValueError(
                        f"registration.externalRegistrations[{index}].{field} must be a non-empty string"
                    )


def _order_registration(registration: dict) -> dict:
    ordered = {}
    for key in CANONICAL_FIELD_ORDER:
        if key in registration:
            ordered[key] = registration[key]
    for key in sorted(registration.keys()):
        if key not in ordered:
            ordered[key] = registration[key]
    return ordered

from dataclasses import dataclass
import os


@dataclass(frozen=True)
class NetworkConfig:
    name: str
    chain_id: int
    rpc_url: str
    explorer_url: str
    identity_registry: str
    enabled: bool

    @property
    def identity_registry_ref(self) -> str:
        return f"eip155:{self.chain_id}:{self.identity_registry}"


RADIUS_TESTNET = NetworkConfig(
    name="testnet",
    chain_id=72344,
    rpc_url="https://rpc.testnet.radiustech.xyz",
    explorer_url="https://testnet.radiustech.xyz",
    identity_registry="0x5cd923Ce1244d5498Bf3f9E0F3a374C2567F1A31",
    enabled=True,
)

RADIUS_MAINNET = NetworkConfig(
    name="mainnet",
    chain_id=0,
    rpc_url="",
    explorer_url="",
    identity_registry="",
    enabled=False,
)

NETWORKS = {
    "testnet": RADIUS_TESTNET,
    "mainnet": RADIUS_MAINNET,
}

DEFAULT_NETWORK = "testnet"


def _env(name: str) -> str:
    return os.environ.get(name, "").strip()


def _with_env_overrides(config: NetworkConfig) -> NetworkConfig:
    prefix = f"ERC8004_{config.name.upper()}"
    chain_id = int(_env(f"{prefix}_CHAIN_ID") or config.chain_id)
    rpc_url = _env(f"{prefix}_RPC_URL") or config.rpc_url
    explorer_url = _env(f"{prefix}_EXPLORER_URL") or config.explorer_url
    identity_registry = _env(f"{prefix}_REGISTRY") or config.identity_registry
    enabled = config.enabled
    if config.name == "mainnet":
        enabled = bool(rpc_url and explorer_url and identity_registry and chain_id)
    return NetworkConfig(
        name=config.name,
        chain_id=chain_id,
        rpc_url=rpc_url,
        explorer_url=explorer_url,
        identity_registry=identity_registry,
        enabled=enabled,
    )


def get_network_config(network: str | None) -> NetworkConfig:
    key = (network or _env("ERC8004_NETWORK") or DEFAULT_NETWORK).strip().lower()
    if key not in NETWORKS:
        raise ValueError(
            f"Unsupported network '{network}'. Expected one of: {', '.join(NETWORKS)}."
        )
    config = _with_env_overrides(NETWORKS[key])
    if not config.enabled:
        raise ValueError(
            f"Radius {config.name} is not configured. Set ERC8004_{config.name.upper()}_RPC_URL, "
            f"ERC8004_{config.name.upper()}_REGISTRY, ERC8004_{config.name.upper()}_EXPLORER_URL, "
            f"and ERC8004_{config.name.upper()}_CHAIN_ID before using this network."
        )
    return config


def supported_networks() -> list[str]:
    return list(NETWORKS.keys())

from copy import deepcopy

from .codec import encode_agent_uri, normalize_registration
from .constants import NetworkConfig


FULL_REGISTRATION_REQUIRED_FIELDS = (
    "type",
    "name",
    "description",
    "image",
    "services",
    "active",
    "supportedTrust",
)


def missing_full_registration_fields(registration: dict) -> list[str]:
    if not isinstance(registration, dict) or not registration:
        return list(FULL_REGISTRATION_REQUIRED_FIELDS)

    missing = []
    for field in FULL_REGISTRATION_REQUIRED_FIELDS:
        if field not in registration:
            missing.append(field)
            continue
        value = registration[field]
        if isinstance(value, str) and not value.strip():
            missing.append(field)
        elif field in {"services", "supportedTrust"} and (
            not isinstance(value, list) or not value
        ):
            missing.append(field)
    return missing


def full_registration_required_error(missing: list[str]) -> str:
    return (
        "erc8004_update_agent_uri requires a complete registration object. "
        "For partial updates, use erc8004_patch_agent_registration or "
        "erc8004_add_ans_pointer. Missing required fields: "
        f"{', '.join(missing)}"
    )


def merge_registration_patch(
    current_registration: dict,
    patch: dict | None,
    *,
    network: NetworkConfig,
) -> tuple[dict, dict]:
    if patch is None:
        patch = {}
    if not isinstance(patch, dict):
        raise ValueError("patch must be a JSON object")

    old_registration = normalize_registration(current_registration, network=network)
    new_registration = deepcopy(old_registration)

    diff = {
        "servicesAdded": [],
        "servicesUpdated": [],
        "aliasesAdded": [],
        "aliasesUpdated": [],
        "externalRegistrationsAdded": [],
        "externalRegistrationsUpdated": [],
        "fieldsChanged": [],
    }

    _apply_fields(new_registration, patch.get("fields"), diff)
    _validate_patch_array(
        patch.get("services_add"),
        "services_add",
        _validate_service_add,
    )
    _validate_patch_array(
        patch.get("services_update"),
        "services_update",
        _validate_service_update,
    )
    _validate_patch_array(patch.get("aliases_add"), "aliases_add", _validate_alias_add)
    _validate_patch_array(
        patch.get("externalRegistrations_add"),
        "externalRegistrations_add",
        _validate_external_registration_add,
    )
    _validate_patch_array(
        patch.get("external_registrations_add"),
        "external_registrations_add",
        _validate_external_registration_add,
    )

    _apply_services(new_registration, patch.get("services_add"), diff, update=False)
    _apply_services(new_registration, patch.get("services_update"), diff, update=True)
    _apply_aliases(new_registration, patch.get("aliases_add"), diff)
    _apply_external_registrations(
        new_registration, patch.get("externalRegistrations_add"), diff
    )
    _apply_external_registrations(
        new_registration, patch.get("external_registrations_add"), diff
    )

    normalized = normalize_registration(new_registration, network=network)
    return normalized, diff


def build_ans_pointer_patch(
    *,
    ans_name: str,
    ans_agent_id: str,
    agent_host: str,
    status: str,
    a2a_url: str,
    web_url: str,
    agent_card_url: str,
    did: str,
) -> dict:
    values = {
        "ans_name": ans_name,
        "ans_agent_id": ans_agent_id,
        "agent_host": agent_host,
        "status": status,
        "a2a_url": a2a_url,
        "web_url": web_url,
        "agent_card_url": agent_card_url,
        "did": did,
    }
    missing = [key for key, value in values.items() if not _non_empty_string(value)]
    if missing:
        raise ValueError(f"Missing required ANS pointer fields: {', '.join(missing)}")

    return {
        "services_add": [
            {
                "name": "web",
                "endpoint": web_url,
                "version": "v1",
                "primary": True,
            },
            {
                "name": "A2A",
                "endpoint": a2a_url,
                "metadata": agent_card_url,
                "version": "0.3.0",
                "primary": True,
            },
            {
                "name": "DID",
                "endpoint": did,
                "version": "v1",
                "primary": True,
            },
            {
                "name": "ANS",
                "endpoint": ans_name,
                "version": "1.0.0",
                "registry": "godaddy-ans",
                "registryId": ans_agent_id,
                "agentHost": agent_host,
                "status": status,
            },
        ],
        "aliases_add": [
            {"type": "web", "endpoint": web_url, "primary": True},
            {"type": "a2a", "endpoint": a2a_url, "primary": True},
            {"type": "did", "endpoint": did, "primary": True},
            {"type": "ans", "endpoint": ans_name, "primary": True},
        ],
        "externalRegistrations_add": [
            {
                "registry": "godaddy-ans",
                "registryId": ans_agent_id,
                "name": ans_name,
                "agentHost": agent_host,
                "version": "1.0.0",
                "status": status,
            }
        ],
    }


def dry_run_patch_result(
    *,
    network_name: str,
    agent_id: int,
    old_registration: dict,
    new_registration: dict,
    diff: dict,
) -> dict:
    data_uri = encode_agent_uri(new_registration)
    return {
        "dryRun": True,
        "network": network_name,
        "agentId": int(agent_id),
        "oldRegistration": old_registration,
        "newRegistration": new_registration,
        "diff": diff,
        "dataUri": data_uri,
        "dataUriBytes": len(data_uri.encode("utf-8")),
        "wouldSubmit": False,
    }


def _apply_fields(registration: dict, fields: dict | None, diff: dict) -> None:
    if fields is None:
        return
    if not isinstance(fields, dict):
        raise ValueError("patch.fields must be an object")
    for key, value in fields.items():
        if registration.get(key) != value:
            registration[key] = deepcopy(value)
            diff["fieldsChanged"].append(key)


def _apply_services(
    registration: dict, services: list[dict] | None, diff: dict, *, update: bool
) -> None:
    if services is None:
        return
    if not isinstance(services, list):
        raise ValueError("patch.services_add and patch.services_update must be arrays")
    target = registration.setdefault("services", [])
    if not isinstance(target, list):
        raise ValueError("registration.services must be an array")
    index = {
        _service_key(item): position
        for position, item in enumerate(target)
        if isinstance(item, dict)
    }
    for service in services:
        if not isinstance(service, dict):
            raise ValueError("patch service entries must be objects")
        key = _service_key(service)
        if key in index:
            position = index[key]
            merged = {**target[position], **deepcopy(service)}
            if merged != target[position]:
                target[position] = merged
                diff["servicesUpdated"].append(merged)
        elif update:
            target.append(deepcopy(service))
            index[key] = len(target) - 1
            diff["servicesAdded"].append(deepcopy(service))
        else:
            target.append(deepcopy(service))
            index[key] = len(target) - 1
            diff["servicesAdded"].append(deepcopy(service))


def _apply_aliases(registration: dict, aliases: list[dict] | None, diff: dict) -> None:
    if aliases is None:
        return
    if not isinstance(aliases, list):
        raise ValueError("patch.aliases_add must be an array")
    target = registration.setdefault("aliases", [])
    if not isinstance(target, list):
        raise ValueError("registration.aliases must be an array")
    index = {
        _alias_key(item): position
        for position, item in enumerate(target)
        if isinstance(item, dict)
    }
    for alias in aliases:
        if not isinstance(alias, dict):
            raise ValueError("patch alias entries must be objects")
        key = _alias_key(alias)
        if key in index:
            position = index[key]
            merged = {**target[position], **deepcopy(alias)}
            if merged != target[position]:
                target[position] = merged
                diff["aliasesUpdated"].append(merged)
        else:
            target.append(deepcopy(alias))
            index[key] = len(target) - 1
            diff["aliasesAdded"].append(deepcopy(alias))


def _apply_external_registrations(
    registration: dict,
    external_registrations: list[dict] | None,
    diff: dict,
) -> None:
    if external_registrations is None:
        return
    if not isinstance(external_registrations, list):
        raise ValueError(
            "patch.externalRegistrations_add and patch.external_registrations_add must be arrays"
        )
    target = registration.setdefault("externalRegistrations", [])
    if not isinstance(target, list):
        raise ValueError("registration.externalRegistrations must be an array")
    index = {
        _external_registration_key(item): position
        for position, item in enumerate(target)
        if isinstance(item, dict)
    }
    for item in external_registrations:
        if not isinstance(item, dict):
            raise ValueError("patch external registration entries must be objects")
        key = _external_registration_key(item)
        if key in index:
            position = index[key]
            merged = {**target[position], **deepcopy(item)}
            if merged != target[position]:
                target[position] = merged
                diff["externalRegistrationsUpdated"].append(merged)
        else:
            target.append(deepcopy(item))
            index[key] = len(target) - 1
            diff["externalRegistrationsAdded"].append(deepcopy(item))


def _service_key(service: dict) -> tuple[str, str]:
    return (
        str(service.get("name", "")).strip().lower(),
        str(service.get("endpoint", "")).strip(),
    )


def _alias_key(alias: dict) -> tuple[str, str]:
    return (
        str(alias.get("type", "")).strip().lower(),
        str(alias.get("endpoint", "")).strip(),
    )


def _external_registration_key(item: dict) -> tuple[str, str]:
    registry = str(item.get("registry", "")).strip().lower()
    registry_id = str(item.get("registryId", "")).strip()
    if registry_id:
        return (registry, registry_id)
    return (
        registry,
        str(item.get("name", "")).strip(),
    )


def _non_empty_string(value: object) -> bool:
    return isinstance(value, str) and bool(value.strip())


def _validate_patch_array(items: object, field_name: str, validator) -> None:
    if items is None:
        return
    if not isinstance(items, list):
        raise ValueError(f"patch.{field_name} must be an array")
    for index, item in enumerate(items):
        if not isinstance(item, dict):
            raise ValueError(f"patch.{field_name}[{index}] must be an object")
        validator(item, f"patch.{field_name}[{index}]")


def _validate_service_add(item: dict, path: str) -> None:
    if not _non_empty_string(item.get("name")) or not _non_empty_string(
        item.get("endpoint")
    ):
        raise ValueError(f"{path} must include non-empty name and endpoint")


def _validate_service_update(item: dict, path: str) -> None:
    if not _non_empty_string(item.get("name")) or not (
        _non_empty_string(item.get("endpoint")) or item.get("selector")
    ):
        raise ValueError(f"{path} must include non-empty name plus endpoint or selector")


def _validate_alias_add(item: dict, path: str) -> None:
    if not _non_empty_string(item.get("type")) or not _non_empty_string(
        item.get("endpoint")
    ):
        raise ValueError(f"{path} must include non-empty type and endpoint")


def _validate_external_registration_add(item: dict, path: str) -> None:
    if not _non_empty_string(item.get("registry")) or not (
        _non_empty_string(item.get("registryId")) or _non_empty_string(item.get("name"))
    ):
        raise ValueError(
            f"{path} must include non-empty registry and registryId or name"
        )

import json
import logging
import os
import subprocess
import sys
import time
import uuid
from urllib.parse import urlparse

import requests


logger = logging.getLogger("a2a-send")


def _get_base_url() -> str:
    if os.environ.get("PUBLIC_URL"):
        return os.environ["PUBLIC_URL"].rstrip("/")
    if os.environ.get("RAILWAY_PUBLIC_DOMAIN"):
        return f"https://{os.environ['RAILWAY_PUBLIC_DOMAIN']}".rstrip("/")
    return f"http://localhost:{os.environ.get('PORT', '3000')}"


def _did_web_to_base_url(did: str) -> str | None:
    if not isinstance(did, str) or not did.startswith("did:web:"):
        return None
    did_path = did.split("#", 1)[0][8:]
    if not did_path:
        return None
    parts = did_path.split(":")
    host = parts[0].replace("%3A", ":")
    if len(parts) == 1:
        return f"https://{host}"
    return f"https://{host}/{'/'.join(parts[1:])}"


def _normalize_target(agent: str | None) -> str:
    if not agent or not str(agent).strip():
        peer = os.environ.get("A2A_PEER_URL", "").strip()
        if peer:
            return peer.rstrip("/")
        raise ValueError("No agent target provided and A2A_PEER_URL is not set.")

    value = str(agent).strip().rstrip("/")
    if value.startswith("did:web:"):
        base_url = _did_web_to_base_url(value)
        if not base_url:
            raise ValueError(f"Unsupported DID target: {value}")
        return base_url

    if value.startswith("http://") or value.startswith("https://"):
        parsed = urlparse(value)
        base = f"{parsed.scheme}://{parsed.netloc}"
        path = parsed.path.rstrip("/")
        for suffix in (
            "/.well-known/agent-card.json",
            "/.well-known/agent-registration.json",
            "/.well-known/agent-skills/index.json",
            "/.well-known/did.json",
            "/a2a",
            "/token",
        ):
            if path.endswith(suffix):
                trimmed = path[: -len(suffix)].rstrip("/")
                return f"{base}{trimmed}" if trimmed else base
        return value

    raise ValueError(
        "Invalid agent target. Expected a base URL, did:web DID, or a discovery document URL."
    )


def _generate_self_signed_token() -> dict:
    result = subprocess.run(
        [sys.executable, "/app/scripts/agent_server/gen_jwt.py"],
        capture_output=True,
        text=True,
    )
    if result.returncode != 0:
        raise RuntimeError(result.stderr.strip() or "Failed to generate A2A token")
    return json.loads(result.stdout)


def _exchange_api_key_for_token(base_url: str, api_key: str, subject: str) -> str:
    response = requests.post(
        f"{base_url}/token",
        headers={"X-Api-Key": api_key, "Content-Type": "application/json"},
        json={"sub": subject},
        timeout=20,
    )
    response.raise_for_status()
    data = response.json()
    token = data.get("token")
    if not token:
        raise RuntimeError("Remote /token response did not include a token")
    return token


def _internal_api_key() -> str:
    return str(os.environ.get("HERMES_API_KEY") or os.environ.get("API_SERVER_KEY") or "").strip()


def _internal_base_url() -> str:
    return f"http://127.0.0.1:{os.environ.get('PORT', '3000')}"


def _notify_session_runtime(path: str, payload: dict) -> None:
    api_key = _internal_api_key()
    if not api_key:
        return
    try:
        requests.post(
            f"{_internal_base_url()}{path}",
            headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
            json=payload,
            timeout=10,
        ).raise_for_status()
    except Exception as err:
        _log_event("session_runtime_error", path=path, error=str(err))


def _post_session_runtime(path: str, payload: dict) -> dict | None:
    api_key = _internal_api_key()
    if not api_key:
        return None
    try:
        response = requests.post(
            f"{_internal_base_url()}{path}",
            headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
            json=payload,
            timeout=10,
        )
        response.raise_for_status()
        data = response.json()
        return data if isinstance(data, dict) else None
    except Exception as err:
        _log_event("session_runtime_error", path=path, error=str(err))
        return None


def _resolve_existing_session(payload: dict) -> dict | None:
    data = _post_session_runtime("/internal/a2a/sessions/resolve", payload)
    session = (data or {}).get("session")
    return session if isinstance(session, dict) and session else None


def _runtime_session(data: dict | None) -> dict | None:
    session = (data or {}).get("session")
    return session if isinstance(session, dict) and session else None


def _build_user_update(session: dict | None, remote_agent: str, context_id: str, auto_continue: bool) -> str:
    if session:
        latest_card = session.get("latest_card") if isinstance(session.get("latest_card"), dict) else None
        if latest_card and latest_card.get("text"):
            return str(latest_card["text"])
        if auto_continue:
            return f"Conversation started with {remote_agent} on context {context_id}. Waiting on the peer agent."
    return f"Sent the A2A message to {remote_agent} on context {context_id}."


def _log_event(event: str, **fields) -> None:
    details = " ".join(
        f"{key}={json.dumps(value, separators=(',', ':')) if isinstance(value, (dict, list)) else value}"
        for key, value in fields.items()
        if value is not None
    )
    logger.info("[a2a-outbound] event=%s%s%s", event, " " if details else "", details)


def register(ctx):
    schema = {
        "name": "send_a2a_message",
        "description": (
            "Send a task to another A2A-compatible agent with built-in sender-side correlation logging. "
            "Returns the remote result plus local correlation ids including rpc_id, a2a_message_id, "
            "context_id, and the remote a2a_task_id."
        ),
        "parameters": {
            "type": "object",
            "properties": {
                "agent": {
                    "type": "string",
                    "description": "Target agent base URL, did:web DID, or discovery URL. Defaults to A2A_PEER_URL if set.",
                },
                "task": {
                    "type": "string",
                    "description": "Task text to send to the remote agent.",
                },
                "context_id": {
                    "type": "string",
                    "description": "Optional existing context_id to continue an A2A thread.",
                },
                "api_key": {
                    "type": "string",
                    "description": "Optional remote JWT exchange key. Defaults to A2A_PEER_API_KEY if set.",
                },
                "subject": {
                    "type": "string",
                    "description": "Optional subject for /token exchange. Defaults to hermes.",
                },
                "session_id": {
                    "type": "string",
                    "description": "Optional durable session id for long-running managed A2A conversations.",
                },
                "goal": {
                    "type": "string",
                    "description": "Optional session goal stored by the local A2A session runtime.",
                },
                "topic": {
                    "type": "string",
                    "description": "Optional short topic label stored by the local A2A session runtime.",
                },
                "auto_continue": {
                    "type": "boolean",
                    "description": "When true, register this exchange as a managed long-running session that can keep sending future turns automatically.",
                },
                "max_turns": {
                    "type": "integer",
                    "description": "Optional managed-session stop limit. Omit for open-ended sessions.",
                },
                "origin_platform": {
                    "type": "string",
                    "description": "Optional user-facing platform label for the originating thread, such as discord.",
                },
                "origin_chat_id": {
                    "type": "string",
                    "description": "Optional originating chat or thread id for observability.",
                },
                "origin_message_id": {
                    "type": "string",
                    "description": "Optional originating message id for observability.",
                },
                "origin_label": {
                    "type": "string",
                    "description": "Optional human label for the originating conversation.",
                },
            },
            "required": ["task"],
        },
    }

    def handle(params, **kwargs):
        params = params or {}
        task = str(params.get("task") or "").strip()
        if not task:
            return "Error sending A2A message: missing task text"

        try:
            base_url = _normalize_target(params.get("agent"))
            api_key = str(params.get("api_key") or os.environ.get("A2A_PEER_API_KEY", "")).strip()
            subject = str(params.get("subject") or "hermes").strip() or "hermes"
            rpc_id = str(uuid.uuid4())
            message_id = str(uuid.uuid4())
            auto_continue = bool(params.get("auto_continue"))
            origin = {
                "platform": str(params.get("origin_platform") or "").strip() or None,
                "chat_id": str(params.get("origin_chat_id") or "").strip() or None,
                "message_id": str(params.get("origin_message_id") or "").strip() or None,
                "label": str(params.get("origin_label") or "").strip() or None,
            }
            requested_context_id = str(params.get("context_id") or "").strip()
            requested_session_id = str(params.get("session_id") or "").strip()
            existing_session = None
            if requested_session_id:
                existing_session = {"session_id": requested_session_id, "context_id": requested_context_id or None}
            else:
                existing_session = _resolve_existing_session(
                    {
                        "remote_agent": base_url,
                        "context_id": requested_context_id or None,
                        "origin": origin,
                    }
                )
            context_id = str(
                requested_context_id
                or (existing_session or {}).get("context_id")
                or ""
            ).strip() or str(uuid.uuid4())
            session_id = str(
                requested_session_id
                or (existing_session or {}).get("session_id")
                or ""
            ).strip() or str(uuid.uuid4())

            if api_key:
                token = _exchange_api_key_for_token(base_url, api_key, subject)
                auth_mode = "token_exchange"
                caller_did = None
            else:
                token_result = _generate_self_signed_token()
                token = token_result["token"]
                caller_did = token_result.get("did")
                auth_mode = "self_signed_jwt"

            payload = {
                "jsonrpc": "2.0",
                "id": rpc_id,
                "method": "message/send",
                "params": {
                    "message": {
                        "role": "ROLE_USER",
                        "id": message_id,
                        "message_id": message_id,
                        "context_id": context_id,
                        "parts": [{"text": task}],
                    }
                },
            }

            outbound_registration = _post_session_runtime(
                "/internal/a2a/sessions/outbound",
                {
                    "session_id": session_id,
                    "remote_agent": base_url,
                    "remote_did": params.get("agent") if str(params.get("agent") or "").startswith("did:web:") else None,
                    "remote_api_key": api_key or None,
                    "context_id": context_id,
                    "message_id": message_id,
                    "task": task,
                    "goal": str(params.get("goal") or "").strip() or None,
                    "topic": str(params.get("topic") or "").strip() or None,
                    "auto_continue": auto_continue,
                    "max_turns": params.get("max_turns"),
                    "origin": origin,
                },
            )

            _log_event(
                "submit",
                remote_agent=base_url,
                rpc_id=rpc_id,
                a2a_message_id=message_id,
                context_id=context_id,
                session_id=session_id,
                reused_session=bool(existing_session),
                auth_mode=auth_mode,
                caller_did=caller_did,
                prompt_chars=len(task),
            )

            started = time.perf_counter()
            response = requests.post(
                f"{base_url}/a2a",
                headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
                json=payload,
                timeout=180,
            )
            duration_ms = round((time.perf_counter() - started) * 1000, 2)
            response.raise_for_status()
            response_json = response.json()
            result = response_json.get("result") or {}

            _log_event(
                "result",
                remote_agent=base_url,
                rpc_id=rpc_id,
                a2a_message_id=message_id,
                context_id=result.get("context_id") or context_id,
                a2a_task_id=result.get("id"),
                session_id=session_id,
                remote_status=getattr(response, "status_code", None),
                duration_ms=duration_ms,
                task_state=((result.get("status") or {}).get("state")),
            )

            outbound_result = _post_session_runtime(
                "/internal/a2a/sessions/outbound-result",
                {
                    "session_id": session_id,
                    "context_id": result.get("context_id") or context_id,
                    "a2a_task_id": result.get("id"),
                    "duration_ms": duration_ms,
                    "response": response_json,
                    "task_state": ((result.get("status") or {}).get("state")),
                },
            )
            runtime_session = _runtime_session(outbound_result) or _runtime_session(outbound_registration)
            user_update = _build_user_update(
                runtime_session,
                base_url,
                result.get("context_id") or context_id,
                auto_continue,
            )

            return json.dumps(
                {
                    "session_id": session_id,
                    "remote_agent": base_url,
                    "auth_mode": auth_mode,
                    "caller_did": caller_did,
                    "rpc_id": rpc_id,
                    "a2a_message_id": message_id,
                    "context_id": result.get("context_id") or context_id,
                    "a2a_task_id": result.get("id"),
                    "duration_ms": duration_ms,
                    "session": runtime_session,
                    "user_update": user_update,
                    "response": response_json,
                },
                indent=2,
            )
        except Exception as err:
            _log_event(
                "error",
                remote_agent=params.get("agent") or os.environ.get("A2A_PEER_URL"),
                error=str(err),
            )
            return f"Error sending A2A message: {err}"

    ctx.register_tool(
        name="send_a2a_message",
        toolset="a2a-send",
        schema=schema,
        handler=handle,
    )

import json
import os
from urllib.parse import urlparse
from urllib.request import Request, urlopen


def _get_base_url() -> str:
    if os.environ.get("PUBLIC_URL"):
        return os.environ["PUBLIC_URL"].rstrip("/")
    if os.environ.get("RAILWAY_PUBLIC_DOMAIN"):
        return f"https://{os.environ['RAILWAY_PUBLIC_DOMAIN']}".rstrip("/")
    return f"http://localhost:{os.environ.get('PORT', '3000')}"


def _did_web_to_base_url(did: str) -> str | None:
    if not isinstance(did, str) or not did.startswith("did:web:"):
        return None
    did_path = did.split("#", 1)[0][8:]
    if not did_path:
        return None
    parts = did_path.split(":")
    host = parts[0].replace("%3A", ":")
    if len(parts) == 1:
        return f"https://{host}"
    return f"https://{host}/{'/'.join(parts[1:])}"


def _normalize_target(agent: str | None) -> str:
    if not agent or not str(agent).strip():
        return _get_base_url()

    value = str(agent).strip().rstrip("/")
    if value.startswith("did:web:"):
        base_url = _did_web_to_base_url(value)
        if not base_url:
            raise ValueError(f"Unsupported DID target: {value}")
        return base_url

    if value.startswith("http://") or value.startswith("https://"):
        parsed = urlparse(value)
        base = f"{parsed.scheme}://{parsed.netloc}"
        path = parsed.path.rstrip("/")
        for suffix in (
            "/.well-known/agent-card.json",
            "/.well-known/agent-registration.json",
            "/.well-known/agent-skills/index.json",
            "/.well-known/did.json",
        ):
            if path.endswith(suffix):
                trimmed = path[: -len(suffix)].rstrip("/")
                return f"{base}{trimmed}" if trimmed else base
        return value

    raise ValueError(
        "Invalid agent target. Expected a base URL, did:web DID, or a discovery document URL."
    )


def _fetch_json(url: str):
    req = Request(
        url,
        headers={
            "Accept": "application/json, application/did+json, text/plain;q=0.8, */*;q=0.5",
            "User-Agent": "hermes-agent-info-plugin/1.0",
        },
    )
    with urlopen(req, timeout=10) as response:
        charset = response.headers.get_content_charset() or "utf-8"
        body = response.read().decode(charset)
    return json.loads(body)


def _fetch_text(url: str) -> str:
    req = Request(
        url,
        headers={
            "Accept": "text/markdown, text/plain;q=0.9, */*;q=0.5",
            "User-Agent": "hermes-agent-info-plugin/1.0",
        },
    )
    with urlopen(req, timeout=10) as response:
        charset = response.headers.get_content_charset() or "utf-8"
        return response.read().decode(charset)


def _get_agent_info(agent: str | None, include_skill_docs: bool) -> dict:
    base_url = _normalize_target(agent)
    agent_card = _fetch_json(f"{base_url}/.well-known/agent-card.json")
    skills_index = _fetch_json(f"{base_url}/.well-known/agent-skills/index.json")
    agent_registration = _fetch_json(f"{base_url}/.well-known/agent-registration.json")
    did_document = _fetch_json(f"{base_url}/.well-known/did.json")
    wallet_address = (
        agent_registration.get("wallet")
        or agent_registration.get("owner")
        or agent_card.get("provider", {}).get("wallet")
    )
    registration_did = None
    for service in agent_registration.get("services", []):
        if isinstance(service, dict) and service.get("name") == "DID":
            registration_did = service.get("endpoint")
            break

    response = {
        "agent": agent or "self",
        "base_url": base_url,
        "did": did_document.get("id")
        or agent_card.get("provider", {}).get("did")
        or registration_did,
        "wallet_address": wallet_address,
        "agent_card": agent_card,
        "skills": skills_index,
        "erc_8004_identity": agent_registration,
        "did_document": did_document,
    }

    if include_skill_docs:
        skill_docs = []
        for skill in skills_index.get("skills", []):
            skill_url = skill.get("url")
            if not skill_url:
                continue
            try:
                skill_docs.append(
                    {
                        "name": skill.get("name"),
                        "url": skill_url,
                        "content": _fetch_text(skill_url),
                    }
                )
            except Exception as err:
                skill_docs.append(
                    {
                        "name": skill.get("name"),
                        "url": skill_url,
                        "error": str(err),
                    }
                )
        response["skill_documents"] = skill_docs

    return response


def register(ctx):
    def get_agent_info(params, **kwargs):
        params = params or {}
        agent = params.get("agent")
        include_skill_docs = params.get("include_skill_docs", True)
        try:
            return json.dumps(
                _get_agent_info(agent, bool(include_skill_docs)),
                indent=2,
            )
        except Exception as err:
            return f"Error retrieving agent info: {err}"

    ctx.register_tool(
        name="get_agent_info",
        toolset="agent-info",
        schema={
            "name": "get_agent_info",
            "description": (
                "Fetch an agent's public discovery metadata in one call, including its A2A "
                "agent card, published skills, ERC-8004 registration, DID document, and "
                "wallet address when publicly advertised. If no agent is provided, the current agent is used."
            ),
            "parameters": {
                "type": "object",
                "properties": {
                    "agent": {
                        "type": "string",
                        "description": (
                            "Optional target agent. Accepts a base URL, a did:web DID, or one "
                            "of the agent's discovery document URLs. Defaults to the current agent."
                        ),
                    },
                    "include_skill_docs": {
                        "type": "boolean",
                        "description": (
                            "Whether to fetch each published SKILL.md document in addition to the "
                            "skills index. Defaults to true."
                        ),
                    },
                },
                "required": [],
            },
        },
        handler=get_agent_info,
    )

