        if not name:
            return "Error: missing required parameter 'name'."
        if records is None:
            if not data:
                return "Error: provide either 'records' or 'data'."
            record: dict[str, Any] = {"data": data}
            for key in ("ttl", "priority", "port", "weight", "protocol", "service"):
