import json
import os
import re
from contextvars import ContextVar
from pathlib import Path


VALID_PROVIDERS = {"local", "para"}
WALLET_TOOL_NAMES = {"radius_wallet_address", "radius_balance", "radius_send_sbc"}
_CURRENT_TASK_ID: ContextVar[str] = ContextVar("radius_cast_task_id", default="")


def _radius_root() -> Path:
    hermes_home = os.environ.get("HERMES_HOME", "/data/.hermes")
    path = Path(hermes_home) / ".radius"
    path.mkdir(parents=True, exist_ok=True)
    return path


def _provider_session_root() -> Path:
    path = _radius_root() / "wallet-provider-sessions"
    path.mkdir(parents=True, exist_ok=True)
    return path


def normalize_provider(value: str | None) -> str:
    provider = str(value or "").strip().lower()
    if provider not in VALID_PROVIDERS:
        raise ValueError(
            f"Invalid wallet provider {value!r}. Expected one of: {', '.join(sorted(VALID_PROVIDERS))}."
        )
    return provider


def _normalize_session_id(session_id: str | None) -> str:
    value = str(session_id or "").strip()
    if not value:
        return ""
    if not re.fullmatch(r"[A-Za-z0-9._:-]{1,200}", value):
        raise ValueError("Invalid session_id")
    return value


def _session_path(session_id: str) -> Path:
    return (_provider_session_root() / f"{_normalize_session_id(session_id)}.json").resolve()


def get_session_provider(session_id: str | None) -> str:
    normalized = _normalize_session_id(session_id)
    if not normalized:
        return "local"
    path = _session_path(normalized)
    if not path.exists():
        return "local"
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return "local"
    provider = str(data.get("provider") or "").strip().lower()
    return provider if provider in VALID_PROVIDERS else "local"


def get_session_record(session_id: str | None) -> dict:
    normalized = _normalize_session_id(session_id)
    if not normalized:
        return {"session_id": "", "provider": "local"}
    path = _session_path(normalized)
    if not path.exists():
        return {"session_id": normalized, "provider": "local"}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {"session_id": normalized, "provider": "local"}
    provider = str(data.get("provider") or "").strip().lower()
    if provider not in VALID_PROVIDERS:
        provider = "local"
    record = {"session_id": normalized, "provider": provider}
    error = str(data.get("error") or "").strip()
    if error:
        record["error"] = error
    return record


def set_session_provider(session_id: str, provider: str) -> str:
    normalized_session_id = _normalize_session_id(session_id)
    normalized_provider = normalize_provider(provider)
    path = _session_path(normalized_session_id)
    payload = {"session_id": normalized_session_id, "provider": normalized_provider}
    path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
    return normalized_provider


def set_session_provider_error(session_id: str, provider: str, error: str) -> str:
    normalized_session_id = _normalize_session_id(session_id)
    normalized_provider = normalize_provider(provider)
    path = _session_path(normalized_session_id)
    payload = {
        "session_id": normalized_session_id,
        "provider": normalized_provider,
        "error": str(error or "").strip(),
    }
    path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
    return normalized_provider


def resolve_provider(explicit_provider: str | None = None, session_id: str | None = None) -> str:
    if explicit_provider not in (None, ""):
        return normalize_provider(explicit_provider)
    record = get_session_record(session_id)
    if record.get("provider") == "para" and record.get("error"):
        raise RuntimeError(record["error"])
    return str(record.get("provider") or "local")


def current_task_id() -> str:
    return str(_CURRENT_TASK_ID.get() or "").strip()


def current_session_id(kwargs: dict | None = None) -> str:
    kwargs = kwargs or {}
    for key in ("task_id", "session_id"):
        value = str(kwargs.get(key) or "").strip()
        if value:
            return value
    return current_task_id()


def pre_tool_call(tool_name: str, args: dict, task_id: str, **kwargs):
    if tool_name in WALLET_TOOL_NAMES:
        _CURRENT_TASK_ID.set(str(task_id or "").strip())


def post_tool_call(tool_name: str, args: dict, result: str, task_id: str, **kwargs):
    if tool_name in WALLET_TOOL_NAMES:
        _CURRENT_TASK_ID.set("")

"""Direct A2A bridge for translating A2A JSON-RPC messages to Hermes chat calls."""
from __future__ import annotations

import time
import uuid
from pathlib import Path
from typing import AsyncIterator
from urllib.parse import quote

from file_utils import allowed_file_paths, detect_file_paths, infer_mime_type, replace_file_paths
from hermes_client import HermesClient


class A2ABridge:
    def __init__(self, hermes_client: HermesClient, allowed_roots: list[Path], public_base_url: str):
        self.hermes_client = hermes_client
        self.allowed_roots = [root.resolve() for root in allowed_roots if root.exists()]
        self.public_base_url = public_base_url.rstrip("/")

    @staticmethod
    def extract_text(message: dict) -> str:
        parts = message.get("parts") or []
        return "\n".join(part.get("text", "") for part in parts if isinstance(part.get("text"), str)).strip()

    @staticmethod
    def context_id(message: dict) -> str:
        return message.get("context_id") or str(uuid.uuid4())

    def _attachments_from_text(self, text: str) -> tuple[str, list[dict]]:
        raw_paths = detect_file_paths(text)
        files = allowed_file_paths(raw_paths, self.allowed_roots)
        if not files:
            return text, []

        replacements: dict[str, str] = {}
        attachments: list[dict] = []
        for file_path in files:
            rel_url = self._to_public_file_path(file_path)
            if not rel_url:
                continue
            display = f"[file: {file_path.name}]"
            replacements[str(file_path)] = display
            attachments.append(
                {
                    "type": "file",
                    "name": file_path.name,
                    "mime_type": infer_mime_type(str(file_path)),
                    "size_bytes": file_path.stat().st_size,
                    "url": rel_url,
                }
            )
        return replace_file_paths(text, replacements), attachments

    def _to_public_file_path(self, file_path: Path) -> str | None:
        for root in self.allowed_roots:
            try:
                rel = file_path.relative_to(root)
                return f"{self.public_base_url}/files/{quote(str(rel))}"
            except ValueError:
                continue
        return None

    async def handle_send(self, rpc_id, message: dict) -> dict:
        user_text = self.extract_text(message)
        if not user_text:
            raise ValueError("Invalid params: no text content in message parts")

        context_id = self.context_id(message)
        task_id = str(uuid.uuid4())
        output = await self.hermes_client.complete(
            messages=[{"role": "user", "content": user_text}],
            session_id=context_id,
        )
        rendered, attachments = self._attachments_from_text(output)
        return {
            "jsonrpc": "2.0",
            "id": rpc_id,
            "result": {
                "id": task_id,
                "context_id": context_id,
                "status": {"state": "TASK_STATE_COMPLETED", "timestamp_ms": int(time.time() * 1000)},
                "message": {
                    "role": "agent",
                    "context_id": context_id,
                    "parts": [{"type": "text", "text": rendered}],
                    **({"attachments": attachments} if attachments else {}),
                },
            },
        }

    async def stream_events(self, rpc_id, message: dict) -> AsyncIterator[dict]:
        user_text = self.extract_text(message)
        if not user_text:
            raise ValueError("Invalid params: no text content in message parts")

        context_id = self.context_id(message)
        full_text = ""
        async for chunk in self.hermes_client.stream(
            messages=[{"role": "user", "content": user_text}],
            session_id=context_id,
        ):
            full_text += chunk
            yield {
                "jsonrpc": "2.0",
                "id": rpc_id,
                "result": {
                    "type": "message.delta",
                    "context_id": context_id,
                    "delta": chunk,
                },
            }

        rendered, attachments = self._attachments_from_text(full_text)
        yield {
            "jsonrpc": "2.0",
            "id": rpc_id,
            "result": {
                "type": "message.completed",
                "context_id": context_id,
                "message": {
                    "role": "agent",
                    "context_id": context_id,
                    "parts": [{"type": "text", "text": rendered}],
                    **({"attachments": attachments} if attachments else {}),
                },
                "status": {"state": "TASK_STATE_COMPLETED", "timestamp_ms": int(time.time() * 1000)},
            },
        }

"""Compatibility boundary for the external A2A SDK.

The A2A SDK has moved error helpers between releases. Keep direct imports from
the SDK in this module so server startup does not depend on private helper paths.
"""
from __future__ import annotations

from typing import Any

from pydantic import BaseModel, ConfigDict


class _FallbackRPCError(BaseModel):
    model_config = ConfigDict(extra="ignore")

    code: int
    data: Any | None = None
    message: str | None = None


try:
    from a2a.types import (  # type: ignore
        InternalError,
        InvalidParamsError,
        InvalidRequestError,
        JSONParseError,
        MethodNotFoundError,
    )
except Exception:

    class InternalError(_FallbackRPCError):
        code: int = -32603
        message: str | None = "Internal error"

    class InvalidParamsError(_FallbackRPCError):
        code: int = -32602
        message: str | None = "Invalid parameters"

    class InvalidRequestError(_FallbackRPCError):
        code: int = -32600
        message: str | None = "Request payload validation error"

    class JSONParseError(_FallbackRPCError):
        code: int = -32700
        message: str | None = "Invalid JSON payload"

    class MethodNotFoundError(_FallbackRPCError):
        code: int = -32601
        message: str | None = "Method not found"


_DEFAULT_ERROR_CODES: dict[type, int] = {
    InternalError: -32603,
    InvalidParamsError: -32602,
    InvalidRequestError: -32600,
    JSONParseError: -32700,
    MethodNotFoundError: -32601,
}


def _model_payload(error_obj: Any) -> dict[str, Any] | None:
    if not hasattr(error_obj, "model_dump"):
        return None
    payload = error_obj.model_dump(by_alias=True, exclude_none=True)
    if isinstance(payload, dict):
        return payload
    return None


def _error_code(error_obj: Any, payload: dict[str, Any]) -> int:
    code = payload.get("code", getattr(error_obj, "code", None))
    try:
        return int(code)
    except (TypeError, ValueError):
        return _DEFAULT_ERROR_CODES.get(type(error_obj), -32603)


def jsonrpc_error_payload(error_obj: Any) -> dict[str, Any]:
    """Return a stable JSON-RPC error dict for SDK or local error objects."""
    root = getattr(error_obj, "root", None)
    if root is not None:
        error_obj = root

    payload = _model_payload(error_obj) or {}
    code = _error_code(error_obj, payload)
    message = payload.get("message", getattr(error_obj, "message", None))
    if not message:
        message = str(error_obj) or "Internal error"

    normalized: dict[str, Any] = {
        "code": code,
        "message": str(message),
    }
    data = payload.get("data", getattr(error_obj, "data", None))
    if data is not None:
        normalized["data"] = data
    return normalized

"""User-facing rendering helpers for managed A2A session updates."""
from __future__ import annotations

from typing import Any


def build_turn_card(session: dict[str, Any], speaker_label: str, text: str) -> dict[str, str]:
    turn_count = int(session.get("turn_count") or 0)
    max_turns = session.get("max_turns")
    turn_label = f"{turn_count}/{max_turns}" if max_turns not in (None, "") else f"{turn_count}/open"
    title = f"Turn {turn_label} • {speaker_label}"
    body = _normalize_text(text)
    footer = _status_footer(session)
    return {"title": title, "body": body, "footer": footer, "text": _as_platform_text(title, body, footer)}


def build_status_card(session: dict[str, Any]) -> dict[str, str]:
    title = "Conversation Active" if session.get("status") == "active" else "Conversation Update"
    body_lines = []
    topic = str(session.get("topic") or session.get("goal") or "").strip()
    if topic:
        body_lines.append(topic)
    waiting_on = session.get("waiting_on")
    if waiting_on == "remote":
        body_lines.append("Waiting on the peer agent.")
    elif waiting_on == "local":
        body_lines.append("Preparing the next local turn.")
    else:
        body_lines.append("No pending turn.")
    footer = _status_footer(session)
    body = "\n".join(body_lines)
    return {"title": title, "body": body, "footer": footer, "text": _as_platform_text(title, body, footer)}


def _status_footer(session: dict[str, Any]) -> str:
    waiting_on = session.get("waiting_on")
    if waiting_on == "remote":
        wait_text = "Waiting on peer"
    elif waiting_on == "local":
        wait_text = "Preparing next turn"
    else:
        wait_text = "Idle"
    context_id = str(session.get("context_id") or "").strip()
    tail = context_id[-8:] if context_id else "unknown"
    return f"{wait_text} • Context {tail}"


def _as_platform_text(title: str, body: str, footer: str) -> str:
    chunks = [title.strip()]
    if body.strip():
        chunks.append("")
        chunks.append(body.strip())
    if footer.strip():
        chunks.append("")
        chunks.append(footer.strip())
    return "\n".join(chunks).strip()


def _normalize_text(text: str) -> str:
    lines = [line.strip() for line in (text or "").splitlines()]
    filtered = [line for line in lines if line]
    collapsed = "\n".join(filtered)
    return collapsed[:1200].strip()

"""Durable session store for long-running A2A conversations."""
from __future__ import annotations

import json
import time
import uuid
from pathlib import Path
from typing import Any

from a2a_render import build_status_card, build_turn_card


class A2ASessionStore:
    def __init__(self, root: Path):
        self.root = root
        self.root.mkdir(parents=True, exist_ok=True)
        self._remote_api_keys: dict[str, str] = {}

    def create_or_update_outbound(self, payload: dict[str, Any]) -> dict[str, Any]:
        now = self._ts()
        session_id = self._normalize_session_id(
            str(payload.get("session_id") or "").strip() or str(uuid.uuid4())
        )
        session = self.get_session(session_id) or self._new_session(session_id, now)

        context_id = str(payload.get("context_id") or session.get("context_id") or "").strip()
        if context_id:
            session["context_id"] = context_id

        remote_agent = str(payload.get("remote_agent") or session.get("remote_agent") or "").strip()
        if remote_agent:
            session["remote_agent"] = remote_agent

        remote_did = str(payload.get("remote_did") or session.get("remote_did") or "").strip()
        if remote_did:
            session["remote_did"] = remote_did

        remote_api_key = str(payload.get("remote_api_key") or "").strip()
        if remote_api_key:
            self._remote_api_keys[session_id] = remote_api_key
        session.pop("remote_api_key", None)

        goal = str(payload.get("goal") or session.get("goal") or "").strip()
        if goal:
            session["goal"] = goal

        topic = str(payload.get("topic") or session.get("topic") or "").strip()
        if topic:
            session["topic"] = topic

        if "max_turns" in payload:
            max_turns = payload.get("max_turns")
            session["max_turns"] = int(max_turns) if max_turns not in (None, "") else None

        if "auto_continue" in payload:
            auto_continue = bool(payload.get("auto_continue"))
        else:
            auto_continue = bool(session.get("auto_continue", False))
        session["auto_continue"] = auto_continue
        session["controller_mode"] = "local" if auto_continue else session.get("controller_mode") or "none"

        origin = payload.get("origin")
        if isinstance(origin, dict):
            merged_origin = dict(session.get("origin") or {})
            merged_origin.update({k: v for k, v in origin.items() if v not in (None, "")})
            session["origin"] = merged_origin

        if payload.get("message_id"):
            session["last_outbound_message_id"] = str(payload["message_id"])

        task_text = str(payload.get("task") or "").strip()
        if task_text:
            self._append_event(
                session,
                {
                    "event": "outbound.submit",
                    "speaker": "local",
                    "message_id": payload.get("message_id"),
                    "context_id": context_id,
                    "text": task_text,
                },
            )
            self._append_transcript(session, "local", task_text)
            session["last_speaker"] = "local"
            session["waiting_on"] = "remote"
            session["next_action"] = "await_remote"
            self._set_latest_card(session, build_turn_card(session, "You", task_text))

        session["status"] = session.get("status") or "active"
        session["updated_at"] = now
        self._save_session(session)
        return session

    def record_outbound_result(self, payload: dict[str, Any]) -> dict[str, Any] | None:
        session_id = str(payload.get("session_id") or "").strip()
        context_id = str(payload.get("context_id") or "").strip()
        session = self.get_session(session_id) if session_id else None
        if not session and context_id:
            session = self.find_by_context(context_id)
        if not session:
            return None

        now = self._ts()
        response = payload.get("response") if isinstance(payload.get("response"), dict) else {}
        result = response.get("result") if isinstance(response.get("result"), dict) else {}
        status = result.get("status") if isinstance(result.get("status"), dict) else {}
        task_state = status.get("state") or payload.get("task_state")
        remote_text = self._extract_message_text(result.get("message"))

        event = {
            "event": "outbound.result",
            "speaker": "remote" if remote_text else "system",
            "context_id": result.get("context_id") or context_id or session.get("context_id"),
            "a2a_task_id": result.get("id") or payload.get("a2a_task_id"),
            "task_state": task_state,
            "duration_ms": payload.get("duration_ms"),
            "text": remote_text,
        }
        self._append_event(session, event)

        resolved_context = str(event["context_id"] or "").strip()
        if resolved_context:
            session["context_id"] = resolved_context

        if remote_text:
            self._append_transcript(session, "remote", remote_text)
            session["turn_count"] = int(session.get("turn_count") or 0) + 1
            session["last_speaker"] = "remote"
            if session.get("auto_continue") and not self._stop_due_to_limit(session):
                session["waiting_on"] = "local"
                session["next_action"] = "compose_local_turn"
                session["next_action_at"] = time.time()
            else:
                session["waiting_on"] = None
                session["next_action"] = "idle"
            self._set_latest_card(session, build_turn_card(session, "Peer Agent", remote_text))
        else:
            session["waiting_on"] = "remote"
            session["next_action"] = "await_remote"
            self._set_latest_status_card(session)

        session["last_remote_state"] = task_state
        session["updated_at"] = now
        session["status"] = "completed" if self._stop_due_to_limit(session) else "active"
        self._save_session(session)
        return session

    def record_inbound_message(self, payload: dict[str, Any]) -> dict[str, Any] | None:
        context_id = str(payload.get("context_id") or "").strip()
        if not context_id:
            return None
        session = self.find_by_context(context_id)
        if not session:
            return None

        now = self._ts()
        message_text = str(payload.get("text") or "").strip()
        if message_text:
            self._append_event(
                session,
                {
                    "event": "inbound.remote_message",
                    "speaker": "remote",
                    "context_id": context_id,
                    "issuer_did": payload.get("issuer_did"),
                    "text": message_text,
                },
            )
            self._append_transcript(session, "remote", message_text)
            session["turn_count"] = int(session.get("turn_count") or 0) + 1
            session["last_speaker"] = "remote"
            if session.get("auto_continue") and not self._stop_due_to_limit(session):
                session["waiting_on"] = "local"
                session["next_action"] = "compose_local_turn"
                session["next_action_at"] = time.time()
            else:
                session["waiting_on"] = None
                session["next_action"] = "idle"
            self._set_latest_card(session, build_turn_card(session, "Peer Agent", message_text))

        issuer = str(payload.get("issuer_did") or "").strip()
        if issuer:
            session["remote_did"] = issuer

        session["updated_at"] = now
        session["status"] = "completed" if self._stop_due_to_limit(session) else "active"
        self._save_session(session)
        return session

    def record_local_turn(self, session_id: str, text: str) -> dict[str, Any] | None:
        session = self.get_session(session_id)
        if not session:
            return None
        if text.strip():
            self._append_event(session, {"event": "local.compose", "speaker": "local", "text": text.strip()})
            self._append_transcript(session, "local", text.strip())
            session["last_speaker"] = "local"
            session["waiting_on"] = "remote"
            session["next_action"] = "await_remote"
            self._set_latest_card(session, build_turn_card(session, "You", text.strip()))
            session["updated_at"] = self._ts()
            self._save_session(session)
        return session

    def mark_error(self, session_id: str, error: str) -> dict[str, Any] | None:
        session = self.get_session(session_id)
        if not session:
            return None
        session["last_error"] = error
        session["status"] = "error"
        session["waiting_on"] = None
        session["next_action"] = "idle"
        self._append_event(session, {"event": "session.error", "speaker": "system", "text": error})
        self._set_latest_status_card(session)
        session["updated_at"] = self._ts()
        self._save_session(session)
        return session

    def mark_paused(self, session_id: str, reason: str) -> dict[str, Any] | None:
        session = self.get_session(session_id)
        if not session:
            return None
        session["status"] = "paused"
        session["waiting_on"] = None
        session["next_action"] = "idle"
        session["pause_reason"] = reason
        session["updated_at"] = self._ts()
        self._append_event(session, {"event": "session.paused", "speaker": "system", "text": reason})
        self._set_latest_status_card(session)
        self._save_session(session)
        return session

    def complete_session(self, session_id: str, reason: str) -> dict[str, Any] | None:
        session = self.get_session(session_id)
        if not session:
            return None
        session["status"] = "completed"
        session["waiting_on"] = None
        session["next_action"] = "idle"
        session["completed_reason"] = reason
        session["updated_at"] = self._ts()
        self._append_event(session, {"event": "session.completed", "speaker": "system", "text": reason})
        self._set_latest_status_card(session)
        self._save_session(session)
        return session

    def list_runnable_sessions(self) -> list[dict[str, Any]]:
        now = time.time()
        runnable: list[dict[str, Any]] = []
        for path in sorted(self.root.glob("*.json")):
            session = self._load_session(path)
            if not session:
                continue
            if session.get("status") != "active":
                continue
            if not session.get("auto_continue"):
                continue
            if session.get("next_action") != "compose_local_turn":
                continue
            if float(session.get("next_action_at") or 0) > now:
                continue
            runnable.append(session)
        return runnable

    def get_session(self, session_id: str) -> dict[str, Any] | None:
        if not session_id:
            return None
        return self._load_session(self._session_path(session_id))

    def find_by_context(self, context_id: str) -> dict[str, Any] | None:
        if not context_id:
            return None
        for path in sorted(self.root.glob("*.json")):
            session = self._load_session(path)
            if session and session.get("context_id") == context_id:
                return session
        return None

    def find_active_session(
        self,
        *,
        remote_agent: str | None = None,
        context_id: str | None = None,
        origin_platform: str | None = None,
        origin_chat_id: str | None = None,
    ) -> dict[str, Any] | None:
        remote_agent = str(remote_agent or "").strip().rstrip("/")
        context_id = str(context_id or "").strip()
        origin_platform = str(origin_platform or "").strip().lower()
        origin_chat_id = str(origin_chat_id or "").strip()

        if context_id:
            session = self.find_by_context(context_id)
            if session and session.get("status") == "active":
                if not remote_agent or str(session.get("remote_agent") or "").strip().rstrip("/") == remote_agent:
                    return session

        if not origin_platform or not origin_chat_id:
            return None

        for path in sorted(self.root.glob("*.json")):
            session = self._load_session(path)
            if not session or session.get("status") != "active":
                continue
            origin = session.get("origin") or {}
            if str(origin.get("platform") or "").strip().lower() != origin_platform:
                continue
            if str(origin.get("chat_id") or "").strip() != origin_chat_id:
                continue
            if remote_agent and str(session.get("remote_agent") or "").strip().rstrip("/") != remote_agent:
                continue
            return session
        return None

    def note_worker_claim(self, session_id: str, delay_seconds: float = 30.0) -> dict[str, Any] | None:
        session = self.get_session(session_id)
        if not session:
            return None
        session["next_action_at"] = time.time() + max(delay_seconds, 1.0)
        session["updated_at"] = self._ts()
        self._save_session(session)
        return session

    def serialize_for_response(self, session: dict[str, Any] | None) -> dict[str, Any] | None:
        if not session:
            return None
        keys = (
            "session_id",
            "context_id",
            "status",
            "goal",
            "topic",
            "auto_continue",
            "max_turns",
            "turn_count",
            "last_speaker",
            "waiting_on",
            "next_action",
            "remote_agent",
            "remote_did",
            "origin",
            "updated_at",
            "created_at",
            "last_error",
        )
        data = {key: session.get(key) for key in keys}
        data["recent_messages"] = list(session.get("recent_messages") or [])
        data["latest_card"] = dict(session.get("latest_card") or {})
        data["recent_cards"] = list(session.get("recent_cards") or [])
        return data

    def get_remote_api_key(self, session_id: str) -> str:
        if not session_id:
            return ""
        return str(self._remote_api_keys.get(self._normalize_session_id(session_id)) or "").strip()

    def _new_session(self, session_id: str, now: str) -> dict[str, Any]:
        return {
            "session_id": session_id,
            "status": "active",
            "goal": "",
            "topic": "",
            "auto_continue": False,
            "max_turns": None,
            "turn_count": 0,
            "last_speaker": None,
            "waiting_on": None,
            "next_action": "idle",
            "next_action_at": 0,
            "context_id": "",
            "remote_agent": "",
            "remote_did": "",
            "origin": {},
            "recent_messages": [],
            "recent_events": [],
            "latest_card": {},
            "recent_cards": [],
            "created_at": now,
            "updated_at": now,
            "controller_mode": "none",
        }

    def _stop_due_to_limit(self, session: dict[str, Any]) -> bool:
        max_turns = session.get("max_turns")
        if max_turns in (None, ""):
            return False
        try:
            return int(session.get("turn_count") or 0) >= int(max_turns)
        except Exception:
            return False

    def _append_transcript(self, session: dict[str, Any], speaker: str, text: str) -> None:
        messages = list(session.get("recent_messages") or [])
        messages.append({"speaker": speaker, "text": text.strip(), "at": self._ts()})
        session["recent_messages"] = messages[-12:]

    def _append_event(self, session: dict[str, Any], event: dict[str, Any]) -> None:
        events = list(session.get("recent_events") or [])
        payload = {key: value for key, value in event.items() if value not in (None, "")}
        payload["at"] = self._ts()
        events.append(payload)
        session["recent_events"] = events[-30:]
        self._append_jsonl(self._events_path(str(session["session_id"])), payload)

    def _save_session(self, session: dict[str, Any]) -> None:
        session_id = self._normalize_session_id(str(session["session_id"]))
        session["session_id"] = session_id
        session.pop("remote_api_key", None)
        path = self._session_path(session_id)
        tmp_path = path.with_suffix(".json.tmp")
        tmp_path.write_text(json.dumps(session, indent=2, sort_keys=True), encoding="utf-8")
        tmp_path.replace(path)

    def _set_latest_card(self, session: dict[str, Any], card: dict[str, str]) -> None:
        cards = list(session.get("recent_cards") or [])
        cards.append({"at": self._ts(), **card})
        session["recent_cards"] = cards[-12:]
        session["latest_card"] = dict(card)

    def _set_latest_status_card(self, session: dict[str, Any]) -> None:
        self._set_latest_card(session, build_status_card(session))

    def _append_jsonl(self, path: Path, payload: dict[str, Any]) -> None:
        with path.open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(payload, separators=(",", ":"), sort_keys=True))
            handle.write("\n")

    def _extract_message_text(self, message: Any) -> str:
        if not isinstance(message, dict):
            return ""
        parts = message.get("parts") or []
        text_parts: list[str] = []
        for part in parts:
            if isinstance(part, dict) and isinstance(part.get("text"), str):
                text_parts.append(part["text"].strip())
        return "\n".join(chunk for chunk in text_parts if chunk).strip()

    def _read_json(self, path: Path) -> dict[str, Any] | None:
        try:
            return json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            return None

    def _load_session(self, path: Path) -> dict[str, Any] | None:
        session = self._read_json(path)
        if not isinstance(session, dict):
            return None
        session_id = str(session.get("session_id") or "").strip()
        if not session_id:
            return None
        try:
            normalized_session_id = self._normalize_session_id(session_id)
        except ValueError:
            return None
        if normalized_session_id != session_id:
            session["session_id"] = normalized_session_id
        if session.pop("remote_api_key", None):
            self._save_session(session)
        return session

    def _session_path(self, session_id: str) -> Path:
        return self._resolve_session_path(self._normalize_session_id(session_id), ".json")

    def _events_path(self, session_id: str) -> Path:
        return self._resolve_session_path(self._normalize_session_id(session_id), ".events.jsonl")

    def _resolve_session_path(self, session_id: str, suffix: str) -> Path:
        path = (self.root / f"{session_id}{suffix}").resolve()
        path.relative_to(self.root.resolve())
        return path

    def _normalize_session_id(self, session_id: str) -> str:
        value = str(session_id or "").strip()
        if not value:
            raise ValueError("session_id is required")
        if "/" in value or "\\" in value or ".." in value:
            raise ValueError("Invalid session_id")
        return value

    def _ts(self) -> str:
        return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())

"""Utilities for detecting and surfacing local file paths in model output."""
from __future__ import annotations

import mimetypes
import re
from pathlib import Path
from typing import Iterable

PATH_RE = re.compile(r"(?P<path>/[\w\-./ ]+)")


def detect_file_paths(text: str) -> list[str]:
    paths: list[str] = []
    seen: set[str] = set()
    for match in PATH_RE.finditer(text or ""):
        candidate = match.group("path").strip().rstrip(".,:;)")
        if len(candidate) < 2:
            continue
        if candidate not in seen:
            seen.add(candidate)
            paths.append(candidate)
    return paths


def infer_mime_type(path: str) -> str:
    mime, _ = mimetypes.guess_type(path)
    return mime or "application/octet-stream"


def replace_file_paths(text: str, replacements: dict[str, str]) -> str:
    rendered = text
    for original, replacement in replacements.items():
        rendered = rendered.replace(original, replacement)
    return rendered


def allowed_file_paths(paths: Iterable[str], allowed_roots: list[Path]) -> list[Path]:
    accepted: list[Path] = []
    for raw in paths:
        path = Path(raw).expanduser()
        try:
            resolved = path.resolve(strict=True)
        except FileNotFoundError:
            continue
        except Exception:
            continue
        if not resolved.is_file():
            continue
        if any(_is_within(resolved, root) for root in allowed_roots):
            accepted.append(resolved)
    return accepted


def _is_within(path: Path, root: Path) -> bool:
    try:
        path.relative_to(root)
        return True
    except ValueError:
        return False

"""Async Hermes OpenAI-compatible chat client."""
from __future__ import annotations

import json
from typing import AsyncIterator, Optional

import httpx


class HermesClientError(Exception):
    """Base exception for Hermes client errors."""


class HermesUnavailableError(HermesClientError):
    """Raised when Hermes is unreachable (network/timeout)."""


class HermesUpstreamError(HermesClientError):
    """Raised when Hermes returns an HTTP error."""


class HermesClient:
    def __init__(self, base_url: str, api_key: str, model: str, timeout: float = 120.0):
        self.base_url = base_url.rstrip("/")
        self.api_key = api_key
        self.model = model
        self._client = httpx.AsyncClient(timeout=timeout)

    def _headers(self, session_id: Optional[str] = None) -> dict:
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
        }
        if session_id:
            headers["X-Hermes-Session-Id"] = session_id
        return headers

    async def complete(self, messages: list[dict], session_id: Optional[str] = None) -> str:
        payload = {"model": self.model, "messages": messages, "stream": False}
        try:
            response = await self._client.post(
                f"{self.base_url}/v1/chat/completions",
                headers=self._headers(session_id),
                json=payload,
            )
            response.raise_for_status()
        except (httpx.ConnectError, httpx.TimeoutException) as exc:
            raise HermesUnavailableError(f"Unable to reach Hermes at {self.base_url}") from exc
        except httpx.HTTPStatusError as exc:
            status = exc.response.status_code if exc.response else "unknown"
            raise HermesUpstreamError(f"Hermes returned HTTP {status}") from exc
        data = response.json()
        choices = data.get("choices") or []
        if not choices:
            return ""
        message = choices[0].get("message") or {}
        return message.get("content") or ""

    async def stream(self, messages: list[dict], session_id: Optional[str] = None) -> AsyncIterator[str]:
        payload = {"model": self.model, "messages": messages, "stream": True}
        try:
            async with self._client.stream(
                "POST",
                f"{self.base_url}/v1/chat/completions",
                headers=self._headers(session_id),
                json=payload,
            ) as response:
                response.raise_for_status()
                async for line in response.aiter_lines():
                    if not line or not line.startswith("data:"):
                        continue
                    raw = line[5:].strip()
                    if raw == "[DONE]":
                        break
                    try:
                        event = json.loads(raw)
                    except json.JSONDecodeError:
                        continue
                    for choice in event.get("choices") or []:
                        delta = (choice.get("delta") or {}).get("content")
                        if delta:
                            yield delta
        except (httpx.ConnectError, httpx.TimeoutException) as exc:
            raise HermesUnavailableError(f"Unable to reach Hermes at {self.base_url}") from exc
        except httpx.HTTPStatusError as exc:
            status = exc.response.status_code if exc.response else "unknown"
            raise HermesUpstreamError(f"Hermes returned HTTP {status}") from exc

    async def close(self):
        await self._client.aclose()

